#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <climits>
using namespace std;

typedef long long ll;
const int MOD=1000000007;
const ll LIM=LLONG_MAX-(ll)MOD*MOD;

class Matrix {
public:
    vector<vector<int>> mat;
    int size;
    Matrix(int s):size(s),mat(s+1,vector<int>(s+1,0)) {}
    void setIdentity() {
        for(int i=0; i<=size; ++i)
            for(int j=0; j<=size; ++j)
                mat[i][j]= (i==j) ? 1 : 0;
    }
};

int gcd(int a,int b) { return b==0?a:gcd(b,a%b); }

ll n; int base;

void multiply(const Matrix &A, const Matrix &B, Matrix &C) {
    int s=A.size;
    for(int i=0; i<=s; ++i)
        for(int j=0; j<=s; ++j) {
            ll sum=0;
            for(int k=0; k<=s; ++k) {
                if(sum>LIM) sum%=MOD;
                sum+= (ll)A.mat[i][k]*B.mat[k][j];
            }
            C.mat[i][j]=sum%MOD;
        }
}

int main() {
    cin>>n>>base;
    int size=base;
    vector<vector<vector<Matrix>>> mat(61, vector<vector<Matrix>>(size, vector<Matrix>(size, Matrix(size))));
    Matrix have(size), tmp(size);
    for(int i=0; i<size; ++i)
        for(int j=0; j<size; ++j)
            for(int k=0; k<=size; ++k)
                for(int l=0; l<=size; ++l)
                    mat[0][i][j][k].mat[k][l]= (k==l || j==l) ? 1 : 0;

    int ci=0; ll step=1;
    while(step<=n/size) {
        ++ci; step*=size;
    }

    for(int i=1; i<=ci; ++i)
        for(int j=0; j<size; ++j) {
            mat[i][j][j][j].setIdentity();
            for(int k=0; k<size; ++k) {
                multiply(mat[i][j][k], mat[i-1][(j+k)%size][k], tmp);
                mat[i][j][k]=tmp;
            }
        }

    have.setIdentity();
    for(int k=0; k<=size; ++k)
        for(int l=0; l<=size; ++l)
            have.mat[k][l]= (k==l) ? 1 : 0;

    for(; ci>=0; --ci, step/=size) {
        int times= (n/step)%size;
        for(int x=0; x<times; ++x) {
            multiply(have, mat[ci][cj][0], tmp);
            have=tmp;
            if(++cj>=size) cj-=size;
        }
    }

    int result=0;
    for(int k=0; k<=size; ++k) {
        result+=have.mat[k][size];
        if(result>=MOD) result-=MOD;
    }
    cout<<result<<endl;
    return 0;
}
